/* @autogenerated */
package net.civeira.phylax.common.security;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Nested;
import org.junit.jupiter.api.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;

import lombok.NonNull;

@DisplayName("RbacAllowListener CDI event observer")
class RbacAuthorizationDecisionListenerUnitTest {

  @Mock
  private Rbac rbac;

  private RbacAuthorizationDecisionListener listener;
  private OperationContext interaction;
  private AutoCloseable mocks;

  static class TestAllowDecision extends AuthorizationDecision {

    public TestAllowDecision(@NonNull OperationContext context, @NonNull Permission permission) {
      super(context, permission);
    }

    @Override
    public String resourceName() {
      return "test-resource";
    }

    @Override
    public String actionName() {
      return "test-action";
    }
  }

  static class TestPropertiesProposal extends PropertiesProposal {

    public TestPropertiesProposal(OperationContext context, Set<String> fields) {
      super(context, fields);
    }

    public TestPropertiesProposal(OperationContext context) {
      super(context);
    }

    @Override
    public String resourceName() {
      return "test-resource";
    }

    @Override
    public String viewName() {
      return "test-view";
    }
  }

  @BeforeEach
  void setUp() {
    mocks = MockitoAnnotations.openMocks(this);
    listener = new RbacAuthorizationDecisionListener(rbac);
    Actor actor =
        Actor.builder().authenticated(true).roles(List.of("admin")).claims(Map.of()).build();
    InvocationSource conn = InvocationSource.builder().request("/test").build();
    interaction = new OperationContext(actor, conn);
  }

  @AfterEach
  void tearDown() throws Exception {
    mocks.close();
  }

  @Nested
  @DisplayName("checkAllow for AllowDecision")
  class CheckAllowDecision {

    @Test
    @DisplayName("Should delegate to rbac when already allowed")
    void shouldDelegateToRbacWhenAlreadyAllowed() {
      // Arrange — create an allowed decision and stub Rbac to also allow
      Permission allow = Permission.allow();
      AuthorizationDecision decision = new TestAllowDecision(interaction, allow);
      Permission rbacResult = Permission.allow();
      when(rbac.checkAllow(interaction.getActor(), "test-resource", "test-action"))
          .thenReturn(rbacResult);

      // Act — invoke the listener on the decision
      listener.checkAuthorization(decision);

      // Assert — the decision remains allowed
      assertTrue(decision.getPermission().isAllowed(),
          "Decision should remain allowed when rbac also allows");
    }

    @Test
    @DisplayName("Should not delegate to rbac when already denied")
    void shouldNotDelegateToRbacWhenAlreadyDenied() {
      // Arrange
      Permission allow = Permission.deny("denied");
      AuthorizationDecision decision = new TestAllowDecision(interaction, allow);

      // Act
      listener.checkAuthorization(decision);

      // Assert
      verify(rbac, never().description("Rbac should not be consulted when already denied"))
          .checkAllow(any(), anyString(), anyString());
      assertFalse(decision.getPermission().isAllowed(), "Decision should remain denied");
    }
  }

  @Nested
  @DisplayName("checkAllow for PropertiesProposal")
  class CheckAllowProperties {

    @Test
    @DisplayName("Should add inaccessible fields to proposal")
    void shouldAddInaccessibleFieldsToProposal() {
      // Arrange
      PropertiesProposal proposal = new TestPropertiesProposal(interaction, new HashSet<>());
      when(rbac.inaccessibleFields(interaction.getActor(), "test-resource", "test-view"))
          .thenReturn(List.of("secret-field", "hidden-field"));

      // Act
      listener.checkProperties(proposal);

      // Assert
      assertTrue(proposal.getFields().contains("secret-field"),
          "Proposal should contain 'secret-field' after listener processes it");
      assertTrue(proposal.getFields().contains("hidden-field"),
          "Proposal should contain 'hidden-field' after listener processes it");
    }
  }
}
